source='''def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]

    def orbit(r, c):
        seen = {(r, c)}
        pending = [(r, c)]
        while pending:
            i, j = pending.pop()
            neighbors = [(j, i)]
            reflected_i = n + 1 - i
            reflected_j = n + 1 - j
            if 0 <= reflected_i < n:
                neighbors.append((reflected_i, j))
            if 0 <= reflected_j < n:
                neighbors.append((i, reflected_j))
            for cell in neighbors:
                if cell not in seen:
                    seen.add(cell)
                    pending.append(cell)
        return seen

    for r in range(n):
        for c in range(n):
            if grid[r][c] != 6:
                continue
            for i, j in orbit(r, c):
                if grid[i][j] != 6:
                    out[r][c] = grid[i][j]
                    break
    return out
'''
